import sys, warnings
warnings.filterwarnings('ignore')
sys.path.insert(0,'/app/work')
from fit2 import *

diurnal={s for s in order if abs(base_coef[s][1])+abs(base_coef[s][2])>0.05}
print("sensors with a diurnal term:",sorted(x.replace('_01','') for x in diurnal))

def pooled_sel(k, sel_sensors, lo=-240, use_raw=False):
    T=[];Y=[];S=[]
    for s in sel_sensors:
        if use_raw:
            # raw normalized value (no diurnal removal), sign-corrected
            x=((series[s]-mid[s])/hw[s])*(-1 if s in neg else 1)
            if s in decoys:
                a,b=decoys[s]; x=x[~((x.index>=pd.Timestamp(a)-pd.Timedelta(minutes=1))&(x.index<=pd.Timestamp(b)+pd.Timedelta(minutes=1)))]
            a,b=op_win[sub_of[s]]; x=x[~((x.index>=pd.Timestamp(a))&(x.index<=pd.Timestamp(b)))]
            t=((x.index-EVENT)/pd.Timedelta(minutes=1)).values.astype(float); y=x.values
        else:
            t,y=sensor_obs(s)
        t=t-delay[s]; sel=t>=lo
        T.append(t[sel]);Y.append(y[sel]);S.append(np.full(sel.sum(),noise_sd[s]))
    return np.concatenate(T),np.concatenate(Y),np.concatenate(S)

def fit(t,y,sg,free_off=False):
    best=None
    for r0 in (0.0005,0.002,0.01,0.03):
        for t00 in (-60,0,30,60,90):
            if free_off:
                f=lambda p:(np.clip(p[1]*np.clip(t-p[0],0,None),0,SAT)-y+p[2])/sg; p0=[t00,r0,0.0]; xs=[30,0.001,0.05]
            else:
                f=lambda p:(np.clip(p[1]*np.clip(t-p[0],0,None),0,SAT)-y)/sg; p0=[t00,r0]; xs=[30,0.001]
            sol=least_squares(f,p0,x_scale=xs)
            if best is None or sol.cost<best.cost: best=sol
    J=best.jac; cov=np.linalg.pinv(J.T@J)
    return best.x[0],np.sqrt(cov[0,0]),best

print("\n(1) onset using ONLY sensors without a diurnal term")
res1={}
for k in subs:
    ss=[s for s in subs[k] if s not in diurnal]
    t,y,sg=pooled_sel(k,ss)
    t0,se,_=fit(t,y,sg); res1[k]=t0
    print(f"{k:13s} sensors={[s.split('_')[1] for s in ss]} t0={t0:7.2f}±{se:.2f}")
print("order:",sorted(res1,key=res1.get))

print("\n(2) onset using RAW normalized values (no diurnal baseline subtraction at all), all four sensors, with a free constant offset")
res2={}
for k in subs:
    t,y,sg=pooled_sel(k,subs[k],use_raw=True)
    t0,se,_=fit(t,y,sg,free_off=True); res2[k]=t0
    print(f"{k:13s} t0={t0:7.2f}±{se:.2f}")
print("order:",sorted(res2,key=res2.get))

print("\n(3) onset using only diurnal-term sensors (baseline-subtracted)")
res3={}
for k in subs:
    ss=[s for s in subs[k] if s in diurnal]
    t,y,sg=pooled_sel(k,ss)
    t0,se,_=fit(t,y,sg); res3[k]=t0
    print(f"{k:13s} sensors={[s.split('_')[1] for s in ss]} t0={t0:7.2f}±{se:.2f}")
print("order:",sorted(res3,key=res3.get))
